head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > removeAllCellClass]<br/>setCellClass() 메소드로 설정한 CSS 클래스를 모든 날짜에서 일괄 제거합니다.",
    "validation" : [
        "removeAllCellClass() 호출 시 setCellClass() 메소드로 설정한 CSS 클래스를 모든 날짜에서 일괄 제거합니다.",
        "removeCellClass() 메소드는 특정 날짜 하나의 CSS 클래스를 제거합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cList = $c.gcm.createCList({});
    let eList = $c.gcm.createEList([]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시 월: 2025-11
}



// setCellClass 일괄 설정
// 여러 날짜에 highlight / important 클래스 설정 후 DOM 카운트 출력
scwin.btn_setCellClass_onclick = function (e) {
    target1.setCellClass("20251115", "highlight");
    target1.setCellClass("20251120", "highlight");
    target1.setCellClass("20251125", "important");

    let highlightCount = target1.render.querySelectorAll('.highlight').length;
    let importantCount = target1.render.querySelectorAll('.important').length;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[setCellClass 후 highlight 클래스 셀 개수] " + highlightCount + "개"
        + " / [setCellClass 후 important 클래스 셀 개수] " + importantCount + "개"
    );
};



// removeAllCellClass 호출 → 모든 setCellClass 클래스 일괄 제거
// validation: removeAllCellClass 호출 시 모든 날짜 클래스 제거
scwin.btn_removeAllCellClass_onclick = function (e) {
    target1.removeAllCellClass();

    let highlightCount = target1.render.querySelectorAll('.highlight').length;
    let importantCount = target1.render.querySelectorAll('.important').length;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[removeAllCellClass 후 highlight 클래스 셀 개수] " + highlightCount + "개"
        + " / [removeAllCellClass 후 important 클래스 셀 개수] " + importantCount + "개"
    );
};



// removeCellClass 호출 → 특정 날짜 하나의 클래스만 제거
// validation: removeCellClass() 메소드는 특정 날짜 하나의 CSS 클래스를 제거합니다.
scwin.btn_removeCellClass_onclick = function (e) {
    // 사전 셋업: highlight / important 다시 설정
    target1.setCellClass("20251115", "highlight");
    target1.setCellClass("20251120", "highlight");
    target1.setCellClass("20251125", "important");

    // 20251115 한 셀의 클래스만 제거
    target1.removeCellClass("20251115");

    let highlightCount = target1.render.querySelectorAll('.highlight').length;
    let importantCount = target1.render.querySelectorAll('.important').length;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[removeCellClass('20251115') 후 highlight 클래스 셀 개수] " + highlightCount + "개"
        + " / [removeCellClass('20251115') 후 important 클래스 셀 개수] " + importantCount + "개"
    );
};
